export const DEMO_ID='demo-cypress';
export function distance(a,b){if(!a||!b)return null;const rad=Math.PI/180,p=a[0]*rad,q=b[0]*rad,x=(b[0]-a[0])*rad,y=(b[1]-a[1])*rad;const h=Math.sin(x/2)**2+Math.cos(p)*Math.cos(q)*Math.sin(y/2)**2;return 6371008.8*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)));}
export const validPoint=p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180;
export const uid=()=>crypto.randomUUID();
export function demoCourse(){return{id:DEMO_ID,name:'Cypress Practice Club',description:'Fictional course · explore the app',source:'demo',holes:Array.from({length:9},(_,i)=>{const y=35+i*.005,x=-80;return{number:i+1,par:[4,4,3,5,4,3,4,5,4][i],tee:[y,x],front:[y+.0029,x+.0007],center:[y+.00305,x+.00072],back:[y+.0032,x+.00074],hazards:[{name:'Fairway bunker',point:[y+.0019,x+.00012]},{name:'Water carry',point:[y+.00235,x+.00115]}],source:'demo'};})};}
export function osmCourse(result,elements){const lines=elements.filter(e=>e.tags?.golf==='hole'&&e.geometry?.length>=2);const holes=lines.sort((a,b)=>(parseInt(a.tags.ref)||999)-(parseInt(b.tags.ref)||999)).map((e,i)=>({number:parseInt(e.tags.ref)||i+1,par:Number(e.tags.par)>=3&&Number(e.tags.par)<=6?Number(e.tags.par):4,parEstimated:!e.tags.par,tee:[e.geometry[0].lat,e.geometry[0].lon],center:[e.geometry.at(-1).lat,e.geometry.at(-1).lon],front:null,back:null,hazards:[],source:'OpenStreetMap',osmId:e.id}));return{id:uid(),name:result.name||result.display_name?.split(',')[0]||'My golf course',description:result.display_name||'OpenStreetMap course',source:'OpenStreetMap',osmUrl:result.osm_type&&result.osm_id?`https://www.openstreetmap.org/${result.osm_type}/${result.osm_id}`:null,center:[Number(result.lat),Number(result.lon)],holes:holes.length?holes:Array.from({length:9},(_,i)=>({number:i+1,par:4,parEstimated:true,hazards:[],source:'manual'}))};}
export function validateCourse(c){if(!c||typeof c.id!=='string'||typeof c.name!=='string'||c.name.length>300||!Array.isArray(c.holes)||!c.holes.length||c.holes.length>36)throw Error('Invalid course. Use a Fairway backup with 1–36 holes.');for(const h of c.holes){if(!Number.isInteger(h.number)||h.number<1||!Number.isInteger(h.par)||h.par<3||h.par>6)throw Error('Invalid hole number or par.');for(const k of ['tee','front','center','back'])if(h[k]!=null&&!validPoint(h[k]))throw Error('Invalid course coordinates.');if(h.hazards!=null&&(!Array.isArray(h.hazards)||h.hazards.length>100||h.hazards.some(v=>typeof v.name!=='string'||!validPoint(v.point))))throw Error('Invalid hazard data.');}if(c.center&&!validPoint(c.center))throw Error('Invalid map center.');return c;}
export function validateBackup(d){if(d?.format!=='fairway-backup'||d.version!==1||!Array.isArray(d.courses)||d.courses.length>200||!Array.isArray(d.rounds)||d.rounds.length>10000)throw Error('Choose a Fairway backup JSON file.');d.courses.forEach(validateCourse);const ids=d.courses.map(c=>c.id);if(new Set(ids).size!==ids.length)throw Error('Duplicate course identifiers.');for(const r of d.rounds){if(!r||typeof r.id!=='string'||typeof r.courseId!=='string'||typeof r.name!=='string'||typeof r.date!=='string'||!Array.isArray(r.holes)||r.holes.length>36||r.holes.some(h=>!h||!Number.isInteger(h.par)||h.par<3||h.par>6||h.score!=null&&(!Number.isInteger(h.score)||h.score<1||h.score>30)||h.putts!=null&&(!Number.isInteger(h.putts)||h.putts<0||h.putts>15)))throw Error('Invalid round data.');if(r.shots!=null&&(!Array.isArray(r.shots)||r.shots.length>1000||r.shots.some(s=>!validPoint(s.start)||!validPoint(s.end)||!Number.isFinite(s.meters)||typeof s.club!=='string')))throw Error('Invalid shot data.');}if(d.bag!=null&&(!Array.isArray(d.bag)||d.bag.length>30||d.bag.some(c=>typeof c.name!=='string'||!Number.isFinite(c.distance)||c.distance<0||c.distance>500)))throw Error('Invalid club distances.');return d;}
// EXIF GPS identifies the camera position only, never the location of objects in the photo.
export function gpsFromJpeg(buffer){try{const d=new DataView(buffer);if(d.getUint16(0)!==0xffd8)return null;let offset=2;while(offset+4<d.byteLength){if(d.getUint8(offset)!==255)break;const marker=d.getUint8(offset+1),length=d.getUint16(offset+2);if(length<2||offset+2+length>d.byteLength)break;if(marker===225&&d.getUint32(offset+4)===0x45786966){const t=offset+10,le=d.getUint16(t)===0x4949;if(d.getUint16(t+2,le)!==42)return null;const u16=p=>d.getUint16(t+p,le),u32=p=>d.getUint32(t+p,le);const entries=p=>Array.from({length:Math.min(u16(p),300)},(_,i)=>p+2+i*12);const gpsEntry=entries(u32(4)).find(p=>u16(p)===0x8825);if(!gpsEntry)return null;const gps=entries(u32(gpsEntry+8));const get=tag=>gps.find(p=>u16(p)===tag);const axis=(tag,refTag)=>{const p=get(tag),r=get(refTag);if(p==null||r==null||u16(p+2)!==5||u32(p+4)!==3)return NaN;const v=u32(p+8);const nums=[0,8,16].map(n=>u32(v+n)/u32(v+n+4));const ref=String.fromCharCode(d.getUint8(t+r+8));return(nums[0]+nums[1]/60+nums[2]/3600)*(['S','W'].includes(ref)?-1:1);};const point=[axis(2,1),axis(4,3)];return validPoint(point)?point:null;}offset+=2+length;}return null;}catch{return null;}}
